CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT DEFAULT '', price REAL, category TEXT DEFAULT '', images TEXT DEFAULT '[]', active INTEGER DEFAULT 0, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, material TEXT DEFAULT '', dims TEXT DEFAULT '', colors TEXT DEFAULT '', lead TEXT DEFAULT '', featured INTEGER DEFAULT 0, weight REAL);
CREATE TABLE IF NOT EXISTS imgs(key TEXT PRIMARY KEY, type TEXT, data TEXT);
CREATE TABLE IF NOT EXISTS cats(slug TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS ship(uf TEXT PRIMARY KEY, base REAL, perkg REAL, days TEXT);
